const crypto = require('crypto');
const payload = $json || {};
const rawText = payload.text ?? payload.message ?? payload.prompt ?? '';
const cleanMessage = rawText.trim();
const userId = payload.user ?? payload.username ?? payload.sender ?? payload.author ?? payload.chatId ?? 'chat-user';
const userDisplay = payload.displayName ?? payload.fullName ?? payload.name ?? userId;
const receivedAt = new Date().toISOString();
const sessionId = payload.sessionId ?? payload.session ?? payload.threadId ?? payload.chatId ?? 'chat-session';
const requestHash = crypto.createHash('sha256').update(`${cleanMessage}-${userId}`).digest('hex');
return [
  {
    json: {
      ...payload,
      text: rawText,
      cleanMessage,
      requestMetadata: {
        userId,
        userDisplay,
        sessionId,
        receivedAt,
        requestHash,
      },
    },
  },
];

const input = $json || {};
const cleanMessage = input.cleanMessage || input.text || '';
const normalized = cleanMessage.toLowerCase();
const signals = [];
const governance = {
  intentLabel: 'general-info',
  riskLevel: 'low',
  needsHumanReview: false,
  hasWriteIntent: false,
  hasDeleteIntent: false,
  requiresVideoReference: false,
  confidence: 0.5,
  notes: [],
};
const includesAny = (keywords) => keywords.some((keyword) => normalized.includes(keyword));
if (includesAny(['list', 'show', 'fetch', 'catalog', 'overview'])) {
  governance.intentLabel = 'inventory';
  governance.confidence = 0.62;
}
if (includesAny(['update', 'edit', 'change', 'replace', 'retitle', 'rewrite'])) {
  governance.intentLabel = 'metadata-update';
  governance.hasWriteIntent = true;
  governance.riskLevel = governance.riskLevel === 'high' ? 'high' : 'medium';
  governance.notes.push('Metadata edit requested');
}
if (includesAny(['delete', 'remove', 'wipe', 'destroy', 'purge'])) {
  governance.intentLabel = 'delete-video';
  governance.hasDeleteIntent = true;
  governance.hasWriteIntent = true;
  governance.riskLevel = 'high';
  governance.needsHumanReview = true;
  governance.notes.push('Destructive keyword detected');
  governance.confidence = 0.78;
}
if (includesAny(['publish', 'schedule', 'privacy', 'public', 'unlisted'])) {
  governance.intentLabel = governance.intentLabel === 'general-info' ? 'visibility-change' : governance.intentLabel;
  governance.hasWriteIntent = true;
  governance.riskLevel = governance.riskLevel === 'high' ? 'high' : 'medium';
  governance.notes.push('Visibility or scheduling change requested');
}
if (!includesAny(['video id', 'videoId', 'https://youtu', 'watch?v='])) {
  governance.requiresVideoReference = governance.intentLabel !== 'inventory';
}
if (cleanMessage.length < 8) {
  governance.notes.push('Message too short for confident routing');
  governance.confidence = Math.min(governance.confidence, 0.45);
}
if (!signals.length && governance.notes.length) {
  signals.push(...governance.notes);
}
const enriched = {
  ...input,
  governance,
  riskSignals: Array.from(new Set([...signals, ...(input.riskSignals || [])])),
};
return [
  {
    json: enriched,
  },
];

const agentPayload = $json || {};
const requestContext = $('UTIL: Detect Risk Signals').item.json || {};
const requestMetadata = requestContext.requestMetadata || {};
const governance = requestContext.governance || {};
const responseText = agentPayload.output || agentPayload.result || agentPayload.text || '';
const summary = responseText.slice(0, 4000);
const slackSummary = [
  `🎬 Request: ${requestContext.cleanMessage || requestContext.text || 'n/a'}`,
  `• Intent: ${governance.intentLabel || 'general'} (${governance.riskLevel || 'low'})`,
  governance.needsHumanReview ? '• Manual review required' : '• Auto-approved',
  responseText ? `• Response: ${responseText}` : '• Response: waiting on agent output',
].join('
');
return [
  {
    json: {
      timestamp: new Date().toISOString(),
      user: requestMetadata.userDisplay || 'unknown',
      sessionId: requestMetadata.sessionId || 'n/a',
      requestHash: requestMetadata.requestHash || '',
      message: requestContext.cleanMessage || requestContext.text || '',
      intent: governance.intentLabel || 'general-info',
      riskLevel: governance.riskLevel || 'low',
      needsHumanReview: Boolean(governance.needsHumanReview),
      governanceNotes: (governance.notes || []).join('; '),
      riskSignals: (requestContext.riskSignals || []).join(', '),
      responseSummary: summary,
      slackSummary,
      trace: JSON.stringify(agentPayload, null, 2).slice(0, 4000),
    },
  },
];
